{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    for key in ("threshold", "calls"):
        if key not in case:
            raise ValueError(f"Missing required key: {key}")
    threshold = case["threshold"]
    calls = case["calls"]
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be a number")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    diagnostics = []
    accepted_call_ids = []
    for i, call in enumerate(calls):
        for key in ("call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable"):
            if key not in call:
                raise ValueError(f"Missing required key '{key}' in call at index {i}")
        call_id = call["call_id"]
        loss_without_call = call["loss_without_call"]
        loss_with_call = call["loss_with_call"]
        prediction_tokens = call["prediction_tokens"]
        parseable = call["parseable"]
        if not isinstance(prediction_tokens, (int, float)) or prediction_tokens < 1:
            raise ValueError(f"prediction_tokens must be >= 1 for call {call_id}")
        gain = loss_without_call - loss_with_call
        normalized_gain = gain / prediction_tokens
        accepted = bool(parseable) and (normalized_gain >= threshold)
        diagnostics.append({
            "call_id": call_id,
            "normalized_gain": normalized_gain,
            "accepted": accepted
        })
        if accepted:
            accepted_call_ids.append(call_id)
    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics
    }
